# Fix: t-cguas.ts -- fn: -> run: (Runner erwartet t.run())
# Ausfuehren: Set-ExecutionPolicy -Scope Process Bypass
#             & "$env:USERPROFILE\Downloads\cg-fix-run.ps1"

$CGUAS_OUT = "C:\Users\bauer\OneDrive\Desktop\chronogrid-impl\monorepo\packages\cg-testkit\src\suites\t-cguas.ts"
$MONOREPO  = "C:\Users\bauer\OneDrive\Desktop\chronogrid-impl\monorepo"
$TESTKIT   = "C:\Users\bauer\OneDrive\Desktop\chronogrid-impl\monorepo\packages\cg-testkit"

Write-Host "[1] Schreibe t-cguas.ts (run: statt fn:)" -ForegroundColor Cyan
$b64 = ""
$bytes = [System.Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes($CGUAS_OUT, $bytes)
Write-Host "    OK  t-cguas.ts neu geschrieben ($($bytes.Length) Bytes)" -ForegroundColor Green

Write-Host ""
Write-Host "[2] Pruefe fn: Vorkommen (sollte 0 sein)" -ForegroundColor Cyan
$check = [System.IO.File]::ReadAllText($CGUAS_OUT)
$fnCount  = ([regex]::Matches($check, 'fn: ')).Count
$runCount = ([regex]::Matches($check, 'run: ')).Count
Write-Host "    fn:  $fnCount (erwartet: 0)" -ForegroundColor $(if ($fnCount -eq 0) { 'Green' } else { 'Red' })
Write-Host "    run: $runCount (erwartet: 11)" -ForegroundColor $(if ($runCount -eq 11) { 'Green' } else { 'Red' })

Write-Host ""
Write-Host "[3] pnpm test (Level 2)" -ForegroundColor Cyan
Set-Location $TESTKIT
node --import tsx/esm src/cli.ts --level 2

if ($LASTEXITCODE -eq 0) {
    Write-Host ""
    Write-Host "ALLE LEVEL-2-TESTS GRUEN" -ForegroundColor Green
} else {
    Write-Host "Noch Fehler (Exit $LASTEXITCODE)" -ForegroundColor Red
    exit 1
}
